{
  "name": "op-anthropic-auth-v2",
  "version": "0.1.3",
  "description": "OpenCode 2 plugin for Anthropic OAuth with Claude Pro/Max",
  "type": "module",
  "main": "./index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode2",
    "anthropic",
    "claude",
    "oauth",
    "auth",
    "plugin"
  ],
  "license": "MIT",
  "author": "parzival1l <nandhu02111997@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/parzival1l/op-anthropic-auth-v2.git"
  },
  "homepage": "https://github.com/parzival1l/op-anthropic-auth-v2#readme",
  "bugs": {
    "url": "https://github.com/parzival1l/op-anthropic-auth-v2/issues"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "test": "node --test",
    "typecheck": "tsc",
    "check": "node --check index.js && npm run typecheck && npm test",
    "pack:dry-run": "npm pack --dry-run"
  },
  "dependencies": {
    "@openauthjs/openauth": "0.4.3"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "0.0.0-beta-18743",
    "@types/node": "24.6.1",
    "typescript": "5.9.3"
  }
}
